SELECT COUNT(*)
FROM user_random_box_tbl
WHERE user_id = #{userId}
  AND issue_reason = #{issueReason}
  AND source_id = #{sourceId}

SELECT COUNT(*)
FROM user_random_box_tbl
WHERE user_id = #{userId}
  AND issue_reason = #{issueReason}
  AND issued_at >= CURDATE()
  AND issued_at  <  DATE_ADD(CURDATE(), INTERVAL 1 DAY)

