UPDATE user_random_box_tbl
SET box_status = 'REVOKED',
    revoked_at = CURRENT_TIMESTAMP,
    revoke_reason = #{revokeReason}
WHERE user_random_box_id = #{userRandomBoxId}
  AND user_id = #{userId}
  AND box_status = #{expectedStatus}
